package io.postfx.ui;

import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.stage.Stage;
import javafx.stage.Window;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

/** The PostFX application icon in every size (generated by IconGenerator). */
public final class AppIcons {
    private static final int[] SIZES = {16, 24, 32, 48, 64, 128, 256};
    private static List<Image> all;

    private AppIcons() {}

    public static synchronized List<Image> all() {
        if (all == null) {
            all = new ArrayList<>();
            for (int s : SIZES) {
                Image img = load(s);
                if (img != null) all.add(img);
            }
        }
        return all;
    }

    public static Image load(int size) {
        try (InputStream in = AppIcons.class.getResourceAsStream("/io/postfx/ui/icons/postfx-" + size + ".png")) {
            return in == null ? null : new Image(in);
        } catch (Exception e) {
            return null;
        }
    }

    public static ImageView view(int size) {
        Image img = load(size >= 64 ? 128 : 64);
        ImageView v = new ImageView(img);
        v.setFitWidth(size);
        v.setFitHeight(size);
        v.setSmooth(true);
        return v;
    }

    /** Sets the icon on a window (stages and dialogs). */
    public static void apply(Window w) {
        if (w instanceof Stage s && s.getIcons().isEmpty()) s.getIcons().setAll(all());
    }
}
